public interface IBillingApi {                       // client-facing delegate contract
    Task<Invoice> CreateInvoiceAsync(CreateInvoice cmd, CancellationToken ct);
}
public sealed class BillingApi(HttpClient http) : IBillingApi {
    public async Task<Invoice> CreateInvoiceAsync(CreateInvoice cmd, CancellationToken ct) {
        using var res = await http.PostAsJsonAsync("/invoices", cmd, ct);
        if (!res.IsSuccessStatusCode) throw new BillingError(res.StatusCode);
        return (await res.Content.ReadFromJsonAsync<Invoice>(ct))!;
    }
}
